UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('45255218-fbad-5613-a1ea-b04f65ec3348', 'b5632d02-468b-536b-8e76-84069b83c411', 'ea40cc18-b2ba-5c4c-895a-eb410a401db9') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('45255218-fbad-5613-a1ea-b04f65ec3348', 'b5632d02-468b-536b-8e76-84069b83c411', 'ea40cc18-b2ba-5c4c-895a-eb410a401db9') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('45255218-fbad-5613-a1ea-b04f65ec3348', 'b5632d02-468b-536b-8e76-84069b83c411', 'ea40cc18-b2ba-5c4c-895a-eb410a401db9') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('45255218-fbad-5613-a1ea-b04f65ec3348', 'b5632d02-468b-536b-8e76-84069b83c411', 'ea40cc18-b2ba-5c4c-895a-eb410a401db9')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));

